export class AudioManager{
 constructor(settings){this.settings=settings;this.ctx=null;this.step=0;this.next=0;this.theme=0;this.active=true;}
 start(){if(!this.ctx){this.ctx=new(window.AudioContext||window.webkitAudioContext)();}if(this.ctx.state==='suspended')this.ctx.resume().catch(()=>{});}
 tone(freq,duration=.1,type='square',volume=.1,delay=0,end=null,music=false){if(!this.ctx||this.settings.muted)return;const t=this.ctx.currentTime+delay,g=this.ctx.createGain(),o=this.ctx.createOscillator();o.type=type;o.frequency.setValueAtTime(freq,t);if(end)o.frequency.exponentialRampToValueAtTime(Math.max(end,20),t+duration);g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(volume*(music?this.settings.music:this.settings.sfx),t+.008);g.gain.exponentialRampToValueAtTime(.001,t+duration);o.connect(g);g.connect(this.ctx.destination);o.start(t);o.stop(t+duration+.02);o.onended=()=>{o.disconnect();g.disconnect();};}
 fx(kind){const notes={menu:[440,660],kiss:[740,1200],cheek:[880,1320],surprise:[988,1480],bear:[196,392,587],storm:[740,880,988,1175],ultimateCuddle:[262,330,392,523],overload:[196,294,392,587,784,1175],finisher:[523,659,784,1046],forehead:[660,990],neck:[330,880],hand:[380,570],hug:[260,520],cuddle:[330,660],lap:[294,587],heart:[180,1200],upper:[220,1400],hit:[180,90],block:[120,60],jump:[210,480],dodge:[120,400],round:[523,659,784],victory:[523,659,784,1046,784,1046],interact:[392,523,659],achievement:[659,784,1046]};const n=notes[kind]||notes.kiss;n.forEach((f,i)=>this.tone(f,kind==='victory'?.3:.14,kind==='block'?'triangle':'square',.14,i*.085,kind==='kiss'?f*1.3:null));}
 tick(){if(!this.ctx||this.settings.muted||!this.active)return;let t=this.ctx.currentTime;if(t<this.next)return;this.next=t+.19;const scale=[261.63,329.63,392,523.25,440,392,329.63,293.66];const tune=[0,2,4,2,3,2,1,2,0,2,5,2,6,2,7,1];const f=scale[tune[(this.step+this.theme*2)%16]];this.tone(f,.16,'triangle',.12,0,null,true);if(this.step%4===0)this.tone(scale[[0,4,6,7][Math.floor(this.step/8)%4]]/2,.35,'triangle',.13,0,null,true);if(this.step%2===0)this.tone(95,.035,'square',.025,0,40,true);this.step++;}
}
